const fs=require('node:fs'),path=require('node:path'),{execFileSync}=require('node:child_process');const sharp=require('./asset-runtime.cjs').sharp();const root=path.resolve(__dirname,'..'),src=path.join(root,'design-source/actor'),out=path.join(src,'previews'),frames=path.join(out,'.frames');fs.mkdirSync(frames,{recursive:true});
const css=fs.readFileSync(path.join(root,'miniprogram/components/mascot-actor/index.wxss'),'utf8'),spec=JSON.parse(fs.readFileSync(path.join(src,'layers.json')));const keyframes={};for(const match of css.matchAll(/@keyframes ([\w-]+)\{((?:[^{}]|\{[^{}]*\})*)\}/g)){const keys=[];for(const rule of match[2].matchAll(/([^{}]+)\{transform:([^}]+)\}/g))for(const percent of rule[1].split(','))keys.push({at:parseFloat(percent)/100,value:rule[2]});keyframes[match[1]]=keys.sort((a,b)=>a.at-b.at);}
